CREATE TABLE lgas(id BIGSERIAL PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE wards(id BIGSERIAL PRIMARY KEY,lga_id BIGINT NOT NULL REFERENCES lgas(id),name TEXT NOT NULL,UNIQUE(lga_id,name));
CREATE TABLE polling_units(id BIGSERIAL PRIMARY KEY,ward_id BIGINT NOT NULL REFERENCES wards(id),code TEXT NOT NULL,name TEXT NOT NULL,UNIQUE(ward_id,code));
CREATE TABLE volunteers(id BIGSERIAL PRIMARY KEY,full_name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT,community TEXT,polling_unit_id BIGINT NOT NULL REFERENCES polling_units(id),over_18 BOOLEAN NOT NULL CHECK(over_18),election_day_available BOOLEAN NOT NULL,training_available BOOLEAN NOT NULL,previous_experience BOOLEAN NOT NULL,smartphone_access BOOLEAN NOT NULL,contact_method TEXT NOT NULL,consent BOOLEAN NOT NULL CHECK(consent),status TEXT NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ DEFAULT now(),UNIQUE(phone,polling_unit_id));
